import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA code for fused LeakyReLU -> multiply -> LeakyReLU
fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_leaky_relu_mul_kernel(
    const float* __restrict__ x,
    const float* __restrict__ multiplier,
    float* __restrict__ out,
    int n, int c, int d, int h, int w,
    float negative_slope) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = n * c * d * h * w;
    if (idx < total) {
        int w_idx = idx % w;
        int h_idx = (idx / w) % h;
        int d_idx = (idx / (w * h)) % d;
        int c_idx = (idx / (w * h * d)) % c;
        int n_idx = idx / (w * h * d * c);  // for completeness, though not used directly

        float val = x[idx];
        // First LeakyReLU
        if (val < 0.0f) {
            val = val * negative_slope;
        }
        // Multiply by the channel-specific multiplier
        float m = multiplier[c_idx];
        val = val * m;
        // Second LeakyReLU
        if (val < 0.0f) {
            val = val * negative_slope;
        }
        out[idx] = val;
    }
}

torch::Tensor fused_leaky_relu_mul(
    torch::Tensor x,
    torch::Tensor multiplier,
    float negative_slope) {

    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(multiplier.is_cuda(), "multiplier must be a CUDA tensor");

    auto n = x.size(0);
    auto c = x.size(1);
    auto d = x.size(2);
    auto h = x.size(3);
    auto w = x.size(4);
    int total = n * c * d * h * w;

    auto out = torch::empty_like(x);

    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    fused_leaky_relu_mul_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        multiplier.data_ptr<float>(),
        out.data_ptr<float>(),
        n, c, d, h, w,
        negative_slope
    );
    return out;
}
"""

fused_ops_cpp_source = r"""
torch::Tensor fused_leaky_relu_mul(torch::Tensor x, torch::Tensor multiplier, float negative_slope);
"""

# Compile the inline CUDA extension
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_leaky_relu_mul"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D transposed convolution, then a fused custom CUDA kernel
    for (LeakyReLU + multiply + LeakyReLU), and finally MaxPool3d.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, multiplier_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size,
                                                 stride=stride, padding=padding,
                                                 output_padding=output_padding)
        self.multiplier = nn.Parameter(torch.randn(multiplier_shape))
        self.max_pool = nn.MaxPool3d(kernel_size=2)

    def forward(self, x):
        x = self.conv_transpose(x)
        # Fused LeakyReLU -> multiply -> LeakyReLU
        x = fused_ops.fused_leaky_relu_mul(x, self.multiplier, 0.2)
        x = self.max_pool(x)
        return x
